INSERT IGNORE INTO knowledge_content (id, species_id, habit, seasons, water, fertilize, breed, faq) VALUES
(1, 1, '喜温暖湿润和半阴环境，忌强光直射，适宜温度18~28℃。', '春:生长期保持湿润;夏:多喷雾增湿;秋:减少浇水;冬:控水防冻', '表土下2cm干了再浇透，约5~7天一次，冬季拉长。', '春秋季每月一次观叶肥，冬季停肥。', '扦插繁殖：剪取带气根的茎段插入水中或土中即可成活。', '[{"q":"叶子发黄怎么办？","a":"多为浇水过多或光照过强，先停水观察并移到半阴处。"}]'),
(2, 2, '喜温暖湿润半阴环境，忌暴晒，适宜温度18~30℃。', '春:保持湿润;夏:喷雾降温;秋:减少浇水;冬:控水', '见干见湿，约5~7天一次，冬季10天以上。', '生长期每月一次稀薄液肥。', '分株或扦插繁殖。', '[{"q":"叶片开裂正常吗？","a":"成年叶自然开裂是龟背竹特征，属正常现象。"}]'),
(3, 3, '耐旱耐阴，喜明亮散射光，怕积水，适宜温度18~27℃。', '春:少浇水;夏:10天一次;秋:控水;冬:断水防冻', '宁干勿湿，约10~15天一次，冬季几乎断水。', '春秋各施一次复合肥即可。', '分株繁殖，切块晾干后栽种。', '[{"q":"叶子变软变皱？","a":"多为浇水过勤烂根，需停水并检查根系。"}]'),
(4, 4, '喜阳光充足、通风良好，耐旱怕涝，适宜温度15~25℃。', '春:逐渐增加光照;夏:正午遮阴;秋:充足光照;冬:室内保暖', '干透浇透，约7~10天一次，冬季15天以上。', '生长期每月一次多肉专用肥。', '叶插繁殖：叶片晾干后平放土面。', '[{"q":"徒长了怎么办？","a":"增加光照、控制浇水，砍头重新扦插。"}]'),
(5, 5, '喜温暖湿润、明亮散射光，忌暴晒和积水，适宜温度18~30℃。', '春:正常浇水;夏:增加喷雾;秋:减少浇水;冬:控水保暖', '见干见湿，约7~10天一次。', '春夏每月一次复合肥。', '播种或扦插繁殖。', '[{"q":"叶片发软下垂？","a":"多为浇水过多或过少，检查土壤干湿度调整。"}]'),
(6, 6, '喜半阴湿润环境，怕强光直射和积水，适宜温度15~25℃。', '春:保持湿润;夏:遮阴通风;秋:减少浇水;冬:控水保暖', '见干见湿，约7~10天一次。', '花期前每月一次磷钾肥。', '分株繁殖，春季最佳。', '[{"q":"夹箭不开花？","a":"多为温差不足或肥料单一，增加昼夜温差并补磷钾肥。"}]');
